"""Original psychopharmacology questions: mechanisms, monitoring and drug selection."""
from qbank_authoring import question,ref
rows=[]
DE=ref('NICE adult depression guideline','https://www.nice.org.uk/guidance/ng222/chapter/Recommendations')
BP=ref('Indian Psychiatric Society bipolar guideline: 2025 update','https://pmc.ncbi.nlm.nih.gov/articles/PMC12900052/')
CI=ref('Citalopram product information','https://www.medicines.org.uk/emc/product/13910/smpc')
def q(stem,answer,others,title,principle,details,application,clinical,table,refs,style='direct'):
    rows.append(question(stem,answer,others,title,principle,details,application,clinical,table,refs,style))

q('An older adult develops hypotonic hyponatremia shortly after an SSRI is started, with inappropriately concentrated urine in a compatible euvolemic setting. Which drug effect should be considered?', 'SSRI-associated inappropriate antidiuresis',[
 ('Primary polydipsia with maximally dilute urine','The urine is inappropriately concentrated rather than maximally dilute.'),('Nephrogenic diabetes insipidus','This causes a water-conservation defect and more often hypernatremia.'),('Pseudohyponatremia as established by low sodium alone','The measured hypotonicity indicates a true water-balance problem.')],
 'New confusion after a psychotropic change can be biochemical','**SSRIs can contribute to hyponatremia, particularly in vulnerable patients.**',['Exclude adrenal, thyroid, volume and other medication causes as appropriate.','Severity and symptoms determine urgency.'],'**Treat the sodium disorder and review the offending medication.**',['Avoid overly rapid correction.','Plan alternative treatment and monitoring according to recurrence risk.'],[['Serum','Hypotonic'],['Urine','Inappropriately concentrated'],['Drug link','Recent SSRI exposure']],[CI],style='clinical_scenario')

q('Why can combining an SSRI with an NSAID increase gastrointestinal bleeding risk?', 'Reduced platelet serotonin uptake can impair platelet function, adding to NSAID-related injury',[
 ('SSRIs reliably increase vitamin K deficiency through antibiotic action','This is not their relevant mechanism.'),('SSRIs directly create therapeutic anticoagulation identical to warfarin','The platelet effect is different from vitamin-K antagonism.'),('The combination has no risk unless the INR is elevated','Platelet-related bleeding risk may occur with a normal INR.')],
 'Normal coagulation times do not exclude drug-related bleeding risk','**Platelets depend on uptake for their serotonin stores.**',['NSAIDs can add mucosal and platelet effects.','Age, prior bleeding and other antithrombotic drugs change risk.'],'**Review the combination and protective strategies when indicated.**',['Choose analgesia and antidepressant treatment with the whole risk profile in mind.','Investigate bleeding symptoms promptly.'],[['SSRI','Platelet serotonin effect'],['NSAID','Mucosal/platelet contribution'],['Assessment','Clinical risk, not INR alone']],[CI])

q('Which antidepressant pair is specifically associated with dose-dependent QT prolongation requiring attention to patient and co-medication risk?', 'Citalopram and escitalopram',[
 ('Every SSRI has an identical QT effect at every dose','Effects differ across drugs and exposure.'),('Bupropion and mirtazapine as an identical pair with the same regulatory dose restrictions','Their profiles and restrictions are not interchangeable.'),('All antidepressants reliably shorten QT','This is incorrect.')],
 'Consider repolarization risk before stacking QT-active drugs','**Risk depends on dose, electrolytes, congenital susceptibility and interactions.**',['Bradycardia, low potassium/magnesium and other QT drugs add concern.','A mean small change does not eliminate individual torsades risk.'],'**Use appropriate ECG and electrolyte review.**',['Follow the current product-specific dose and contraindication guidance.','Choose an alternative when the risk profile is unsuitable.'],[['Drugs','Citalopram/escitalopram'],['Modifiers','Dose/electrolytes/interactions'],['Plan','Individual cardiac safety review']],[ref('NHS SPS QT-prolonging medicines guidance','https://sps.nhs.uk/articles/commonly-used-medicines-associated-with-qt-interval-prolongation/')])

q('A depressed patient has prominent insomnia and poor appetite with weight loss. If medication is chosen, which option has a profile that may help these symptoms but needs weight/sedation counseling?', 'Mirtazapine',[
 ('Bupropion selected specifically for its usual sedating and appetite-increasing profile','Bupropion is generally more activating and has a different appetite profile.'),('A stimulant as the routine first-line depressive treatment','This is not the usual evidence-based first-line approach.'),('A high-potency antipsychotic alone as the default for nonpsychotic depression','This does not match the described treatment goal.')],
 'Adverse-effect profiles can sometimes align with symptoms','**Mirtazapine can cause sedation and increased appetite/weight.**',['These effects may be helpful or problematic depending on the person.','Assess other causes of weight loss rather than assuming depression alone.'],'**Choose collaboratively and monitor function and metabolic burden.**',['Review morning sedation and falls risk.','Do not treat symptom matching as proof of greater antidepressant efficacy for everyone.'],[['Potential advantage','Sleep/appetite'],['Trade-off','Sedation/weight gain'],['Selection','Individual priorities']],[DE],style='clinical_scenario')

q('Which history is a major contraindication to bupropion because of seizure risk?', 'Current or prior anorexia nervosa or bulimia nervosa',[
 ('Uncomplicated seasonal allergic rhinitis','This is not the corresponding major contraindication.'),('A remote uncomplicated appendectomy','This does not confer the same medication-specific risk.'),('Stable corrected refractive error','This is unrelated to the relevant seizure-risk contraindication.')],
 'Prescribing history must include eating disorders and seizure risk','**Bupropion lowers the seizure threshold in a dose- and risk-dependent way.**',['A seizure disorder and abrupt alcohol/sedative withdrawal are also important contraindication/risk contexts.','Review interacting drugs and dosing formulation.'],'**Choose an alternative when contraindicated.**',['Do not assume a remote eating-disorder history is irrelevant.','Avoid dose stacking or rapid unapproved escalation.'],[['Eating-disorder history','Important contraindication'],['Other risk','Seizure disorder/withdrawal'],['Action','Alternative treatment']],[ref('FDA bupropion safety labeling','https://www.accessdata.fda.gov/drugsatfda_docs/label/2016/018644s050,020358s057lbl.pdf')])

q('A patient taking an irreversible nonselective MAOI develops severe headache and hypertension after a high-tyramine meal. Which mechanism best explains this?', 'Reduced tyramine metabolism permits excessive norepinephrine release',[
 ('Tyramine directly blocks all alpha receptors','That would not explain this hypertensive mechanism.'),('The meal causes opioid receptor antagonism','This is unrelated.'),('MAO inhibition guarantees reduced catecholamine availability','It can increase monoamine effects and creates important interactions.')],
 'Diet and drug interactions are central to MAOI safety','**Normally metabolized dietary amines can have exaggerated pressor effects.**',['Assess the emergency and treat according to severity.','Serotonergic combinations create a separate toxicity risk.'],'**Provide precise food, medication and washout counseling.**',['Over-the-counter sympathomimetics can be hazardous.','Do not use one generic washout interval for every drug without checking its half-life and guidance.'],[['Interaction','Tyramine'],['Effect','Catecholamine release'],['Prevention','Diet/drug and washout planning']],[DE],style='clinical_scenario')

q('A woman with bipolar disorder is considering pregnancy while taking valproate. Which principle is correct?', 'Arrange specialist preconception review because of major fetal malformation and neurodevelopmental risks',[
 ('Assume a low dose eliminates fetal risk','Risk is not abolished by a low dose.'),('Stop every psychotropic abruptly without a relapse plan','Abrupt changes can cause serious maternal illness; review must be planned.'),('Use folate as a guarantee that valproate becomes safe','Folate does not eliminate the specific risks.')],
 'Reproductive planning is part of ongoing mood-disorder care','**Valproate has important teratogenic and developmental hazards.**',['Use current local restrictions and pregnancy-prevention requirements.','Alternative treatment depends on polarity, past response and risk.'],'**Coordinate psychiatric and obstetric planning before conception when possible.**',['Discuss reliable contraception until a safe plan is established.','Do not generalize one country’s administrative rules as universal law.'],[['Risk','Malformation/neurodevelopment'],['Action','Specialist preconception review'],['Medication change','Planned, not abrupt']],[BP,ref('MHRA valproate reproductive risk information','https://www.gov.uk/guidance/valproate-reproductive-risks')],style='clinical_scenario')

q('A valproate-treated patient becomes lethargic and confused with raised ammonia but normal aminotransferases. Which possibility should be considered?', 'Valproate-associated hyperammonemic encephalopathy',[
 ('Normal aminotransferases exclude any valproate-related encephalopathy','Hyperammonemia can occur without major liver-test abnormalities.'),('The ammonia proves cirrhosis regardless of history','There are noncirrhotic causes of hyperammonemia.'),('A therapeutic total drug level makes an adverse effect impossible','Toxicity can depend on factors not captured by a single total concentration.')],
 'Drug toxicity need not follow a classic liver-injury pattern','**Valproate can impair ammonia handling.**',['Topiramate and metabolic susceptibility can contribute.','Assess other causes of altered consciousness and hyperammonemia.'],'**Review/withhold the drug as indicated and obtain urgent specialist treatment.**',['Selected cases warrant carnitine and severe cases extracorporeal assessment.','Follow clinical and biochemical recovery.'],[['Ammonia','Elevated'],['Liver enzymes','Can be normal'],['Diagnosis','Medication-related encephalopathy in context']],[ref('Valproic acid prescribing information','https://www.dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=597a6144-324b-9533-e053-2991aa0ab896&type=display')],style='clinical_scenario')

q('A stable lithium patient develops coarse tremor and ataxia after a thiazide is added. What is the most relevant interaction?', 'Reduced renal lithium clearance can raise lithium exposure',[
 ('Thiazides always increase lithium clearance','They can increase proximal lithium reabsorption through sodium/volume effects.'),('The neurological symptoms are proof of a manic relapse','Ataxia and coarse tremor suggest toxicity rather than mania.'),('A previously normal lithium level excludes a new interaction','Levels can change after medication or physiological changes.')],
 'A new nonpsychiatric prescription can destabilize lithium safety','**Sodium and volume handling affect lithium reabsorption.**',['NSAIDs and renin–angiotensin-system drugs can also cause important interactions.','Dehydration and AKI can amplify risk.'],'**Urgently assess the level, kidney function, electrolytes and clinical toxicity.**',['Withhold/review interacting treatment as indicated.','Severe symptoms require toxicology/nephrology assessment rather than a level-only decision.'],[['Trigger','Thiazide'],['Mechanism','Lower lithium clearance'],['Action','Clinical and biochemical toxicity assessment']],[BP],style='clinical_scenario')

q('Which principle best describes lithium treatment decisions around pregnancy?', 'Use an individualized maternal–fetal risk assessment and specialist monitoring rather than assuming either no risk or an absolute universal prohibition',[
 ('Lithium has no fetal or perinatal risk','Risk counseling and monitoring are necessary.'),('Every stable patient must stop abruptly on a positive test','Abrupt discontinuation can increase relapse risk and needs specialist planning.'),('Valproate is automatically the safer replacement in all pregnancies','Valproate has major reproductive hazards and is not an automatic safe substitute.')],
 'Balance the illness risk with medication-specific risk','**Lithium exposure and clearance change during pregnancy and postpartum.**',['Cardiac malformation risk and perinatal toxicity require discussion in absolute as well as relative terms.','Severe recurrent maternal illness can also threaten health.'],'**Coordinate psychiatry, obstetrics and appropriate fetal/neonatal monitoring.**',['Plan level checks and dose review as physiology changes.','Avoid abrupt unsupervised medication changes.'],[['Decision','Individual benefit-risk'],['Monitoring','Maternal levels and fetal/perinatal care'],['Alternative','Not automatically valproate']],[BP],style='clinical_scenario')

q('A patient taking risperidone develops galactorrhea and menstrual disturbance with elevated prolactin. Which mechanism is most relevant?', 'D2 blockade in the tuberoinfundibular pathway removes dopamine-mediated prolactin inhibition',[
 ('Dopamine blockade invariably lowers prolactin','Dopamine normally inhibits prolactin release.'),('The result necessarily proves a pituitary macroadenoma','Medication is a plausible cause, although other causes may need assessment.'),('Serotonin reuptake inhibition is risperidone’s only relevant action','It is an antipsychotic with dopamine receptor effects.')],
 'Pathway-specific pharmacology explains an endocrine adverse effect','**Reduced dopamine inhibition can raise prolactin.**',['Symptoms, degree, timing and alternative causes guide evaluation.','Pregnancy, thyroid disease and pituitary pathology may need consideration.'],'**Review the antipsychotic strategy without compromising psychiatric stability.**',['Dose adjustment, switching or selected adjunctive approaches may be appropriate.','Assess bone and sexual/reproductive consequences when persistent.'],[['Pathway','Tuberoinfundibular'],['Dopamine','Inhibits prolactin'],['Blockade','Prolactin may rise']],[ref('NICE psychosis medication monitoring','https://www.nice.org.uk/guidance/cg178/chapter/recommendations')],style='clinical_scenario')

q('A patient has persistent disabling tardive dyskinesia after long-term dopamine-receptor-blocking exposure. Which drug class has evidence for targeted symptom treatment?', 'VMAT2 inhibitors such as valbenazine or deutetrabenazine where available',[
 ('Routine anticholinergics as the preferred tardive dyskinesia treatment','They are useful for some other extrapyramidal syndromes and can worsen TD.'),('A large increase in the same antipsychotic as a durable cure','Masking movements does not resolve the underlying syndrome and can increase long-term burden.'),('Cholinesterase reactivators','These are not the targeted TD class.')],
 'Distinguish tardive movements from acute dystonia and parkinsonism','**VMAT2 inhibition reduces presynaptic monoamine packaging and can reduce TD severity.**',['Review the causative drug and the feasibility of modification.','Balance psychiatric stability against movement burden.'],'**Use a structured movement assessment and specialist plan.**',['Monitor adverse effects and interactions of the selected treatment.','Do not abruptly stop essential psychiatric care without an alternative.'],[['TD','Chronic exposure-related movements'],['Targeted option','VMAT2 inhibitor'],['Whole plan','Drug review and functional assessment']],[ref('Evidence-based tardive dyskinesia treatment recommendations','https://pmc.ncbi.nlm.nih.gov/articles/PMC6591749/')])
